/**
 * Sidebar configuration.
 *
 * One sidebar per topic, scoped to that topic only, so browsing Docker never
 * shows Kubernetes pages. The topic's generated page list is preceded by a
 * designed rail header and followed by quick study actions.
 *
 * Everything inside the rail is generated from the docs/ tree. Adding a topic
 * folder, a page, or a grouped subfolder requires no edit here —
 * `autogenerated` walks subdirectories and picks up their _category_.json for
 * grouping.
 *
 * @see https://docusaurus.io/docs/sidebar
 */

const { getTopicDirs, findTopicPages } = require('./scripts/topics');
const { topicLabel } = require('./scripts/lib/content-paths');

/**
 * Generated by the content pipeline before Docusaurus starts. Stats are
 * optional so a bare `docusaurus start` still works during setup.
 *
 * @type {null|{topics: Array<{slug: string, questionCount: number, pageCount: number}>}}
 */
let stats = null;
try {
  stats = require('./src/data/topics.json');
} catch {
  stats = null;
}

/**
 * @param {string} value
 * @returns {string}
 */
function escapeHtml(value) {
  return String(value).replace(
    /[&<>"']/g,
    (char) =>
      ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;',
      })[char]
  );
}

/**
 * The designed header at the top of a topic rail.
 *
 * @param {string} topic
 * @returns {string}
 */
function topicRailHeader(topic) {
  const label = topicLabel(topic);
  const stat = stats?.topics?.find((item) => item.slug === topic);
  const questionCount = stat?.questionCount;
  const pageCount = stat?.pageCount ?? findTopicPages(topic).length;

  const meta = [
    questionCount != null ? `${questionCount} questions` : null,
    `${pageCount} page${pageCount === 1 ? '' : 's'}`,
  ]
    .filter(Boolean)
    .join(' · ');

  return `
    <div class="topicRailHead">
      <a class="topicRailBack" href="/">&larr; All topics</a>
      <span class="topicRailKicker">Topic</span>
      <span class="topicRailTitle">${escapeHtml(label)}</span>
      <span class="topicRailMeta">${escapeHtml(meta)}</span>
    </div>
  `.trim();
}

/**
 * Study actions pinned under the page list.
 *
 * @returns {string}
 */
function topicRailFooter() {
  return `
    <div class="topicRailActions">
      <a class="topicRailAction" href="/revise">Revise due cards <span aria-hidden="true">&rarr;</span></a>
      <a class="topicRailAction" href="/drill">Run a drill <span aria-hidden="true">&rarr;</span></a>
    </div>
  `.trim();
}

/** @type {import('@docusaurus/plugin-content-docs').SidebarsConfig} */
const sidebars = {
  // The intro page stands alone; it belongs to no topic.
  introSidebar: ['intro'],
};

for (const topic of getTopicDirs()) {
  sidebars[`${topic}Sidebar`] = [
    { type: 'html', value: topicRailHeader(topic) },
    { type: 'autogenerated', dirName: topic },
    { type: 'html', value: topicRailFooter(), className: 'topicRailActionsItem' },
  ];
}

module.exports = sidebars;
